import 'package:codar/src/app/providers.dart';
import 'package:codar/src/brand/codar_brand.dart';
import 'package:codar/src/l10n/strings.dart';
import 'package:codar/src/presentation/widgets/app_components.dart';
import 'package:codar/src/reader/locator_nav.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

class LibraryScreen extends ConsumerWidget {
  const LibraryScreen({super.key});
  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final locale = ref.watch(localeProvider); final query = ref.watch(libraryQueryProvider); final books = ref.watch(booksListProvider);
    ref.watch(reconcileProvider); ref.watch(_coverWarmupProvider);
    return Scaffold(backgroundColor: CodarColors.background, appBar: AppBar(title: Text(tr(locale, 'library')), actions: [IconButton(tooltip: query.grid ? tr(locale, 'listView') : tr(locale, 'gridView'), onPressed: () => ref.read(libraryQueryProvider.notifier).set(query.copyWith(grid: !query.grid)), icon: Icon(query.grid ? Icons.view_list_rounded : Icons.grid_view_rounded)), PopupMenuButton<String>(onSelected: (v) => ref.read(libraryQueryProvider.notifier).set(query.copyWith(order: v)), itemBuilder: (_) => [PopupMenuItem(value: 'recent', child: Text(tr(locale, 'sortRecent'))), PopupMenuItem(value: 'added', child: Text(tr(locale, 'sortAdded'))), PopupMenuItem(value: 'title', child: Text(tr(locale, 'sortTitle'))), PopupMenuItem(value: 'author', child: Text(tr(locale, 'sortAuthor')))])]), body: Column(children: [Padding(padding: const EdgeInsets.fromLTRB(20, 8, 20, 12), child: AppSearchField(hint: tr(locale, 'searchHint'), value: query.text, onChanged: (v) => ref.read(libraryQueryProvider.notifier).set(query.copyWith(text: v)), onClear: () => ref.read(libraryQueryProvider.notifier).set(query.copyWith(text: '')))), SingleChildScrollView(scrollDirection: Axis.horizontal, padding: const EdgeInsets.only(left: 20, right: 20, bottom: 16), child: Row(children: [AppChip(label: tr(locale, 'all'), selected: !query.onlyFavorites, onSelected: (_) => ref.read(libraryQueryProvider.notifier).set(query.copyWith(onlyFavorites: false))), const SizedBox(width: 8), AppChip(label: tr(locale, 'favorites'), selected: query.onlyFavorites, onSelected: (v) => ref.read(libraryQueryProvider.notifier).set(query.copyWith(onlyFavorites: v))) ])), Expanded(child: books.when(loading: () => const Center(child: CircularProgressIndicator(color: CodarColors.gold)), error: (e, _) => Center(child: Text('${tr(locale, 'errorPrefix')}: $e')), data: (items) { if (items.isEmpty) return CodarEmptyState(icon: query.text.isEmpty ? Icons.auto_stories_outlined : Icons.search_off_rounded, title: query.text.isEmpty ? tr(locale, 'library') : tr(locale, 'noResults'), subtitle: query.text.isEmpty ? tr(locale, 'noBooks') : tr(locale, 'noResults'), actionLabel: query.text.isEmpty ? tr(locale, 'importBook') : null, onAction: query.text.isEmpty ? () => _import(context, ref) : null); return LayoutBuilder(builder: (c, size) { final grid = query.grid; if (!grid) return ListView.separated(padding: const EdgeInsets.fromLTRB(20, 4, 20, 28), itemCount: items.length, separatorBuilder: (_, _) => const SizedBox(height: 12), itemBuilder: (_, i) => SizedBox(height: 116, child: BookCard(book: items[i], variant: BookCardVariant.horizontal))); return GridView.builder(padding: const EdgeInsets.fromLTRB(20, 4, 20, 28), gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(crossAxisCount: libraryGridColumns(size.maxWidth), mainAxisExtent: 250, crossAxisSpacing: 16, mainAxisSpacing: 22), itemCount: items.length, itemBuilder: (_, i) => BookCard(book: items[i])); }); }))]), floatingActionButton: FloatingActionButton(backgroundColor: CodarColors.gold, foregroundColor: CodarColors.background, onPressed: () => _import(context, ref), child: const Icon(Icons.add_rounded)));
  }
  Future<void> _import(BuildContext context, WidgetRef ref) async { final locale = ref.read(localeProvider); try { final res = await ref.read(importServiceProvider).importWithPicker(); if (res == null) return; ref.read(libraryRefreshProvider.notifier).bump(); if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(res.isNew ? tr(locale, 'importOk') : tr(locale, 'alreadyImported')))); } on Exception catch (e) { if (context.mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('${tr(locale, 'importFailed')}: $e'))); } }
}
final _coverWarmupProvider = FutureProvider<void>((ref) async { final enabled = await ref.read(settingsRepoProvider).appValue('enrich_online', '0') == '1'; if (!enabled) return; final books = await ref.read(booksRepoProvider).listBooks(order: 'recent'); final enrichment = ref.read(enrichmentServiceProvider); for (final b in books) { await enrichment.enrich(b.bookId, onlineAllowed: true); } });
